//
// D2's built-in `paper` and `grain` fill patterns (d2renderers/internal/patternassets, v0.9.0): the SVG pattern definitions are
// big (paper is 435 KB of text), so they live in public/d2/patterns/*.svg.txt and are fetched on first use, one file per pattern.
// Generated by tools/d2ref/genpatterns.mjs.

import { NeedAsset } from './d2svg.js';

const cache = new Map();
let baseURL = new URL('./patterns/', import.meta.url);
export function setPatternBaseURL(u) { baseURL = new URL(u, import.meta.url); }

/** Loads one pattern definition ('paper' or 'grain'). */
export async function loadPattern(name) {
  if (cache.has(name)) return;
  const u = new URL(`${name}.svg.txt`, baseURL);
  if (typeof process !== 'undefined' && process.versions?.node && u.protocol === 'file:') {
    const fs = await import('node:fs/promises');
    cache.set(name, await fs.readFile(u, 'utf8'));
  } else {
    const res = await fetch(u);
    if (!res.ok) throw new Error(`d2svg: cannot load pattern ${u}: ${res.status}`);
    cache.set(name, await res.text());
  }
}

function get(name) {
  const s = cache.get(name);
  if (s === undefined) throw new NeedAsset('pattern', name);
  return s;
}

export const paperSVG = () => get('paper');
export const grainSVG = () => get('grain');
